const staticData = $getWorkflowStaticData('global');
staticData.rotationIndex = (staticData.rotationIndex || 0) + 1;

const cities = [
  'Austin, TX', 'London, UK', 'Sydney, Australia', 'Miami, FL', 'Toronto, Canada',
  'Chicago, IL', 'Melbourne, Australia', 'New York, NY', 'Denver, CO', 'Manchester, UK',
  'San Francisco, CA', 'Vancouver, Canada', 'Atlanta, GA', 'Brisbane, Australia', 'Dallas, TX'
];

const config = $('Config: VA Profile & Settings').first().json;
const role = config.va_role || 'Automation VA';

const nichesByRole = {
  'Automation VA': [
    // 1. Agency Partners & AAAs (Overflow / Subcontracting)
    { query: 'AI Automation Agency', plural: 'automation agencies', pain: 'client workflow delivery and n8n overflow development' },
    { query: 'Lead Generation Agency', plural: 'lead generation agencies', pain: 'speed-to-lead routing and client CRM automation' },
    { query: 'Web Design Agency', plural: 'web design studios', pain: 'client form handoffs and backend workflow integrations' },
    { query: 'Digital Marketing Agency', plural: 'digital agencies', pain: 'inquiry intake and client onboarding' },

    // 2. High-Ticket Trade Contractors
    { query: 'Commercial Roofing Contractor', plural: 'commercial roofers', pain: 'job completion and review collection' },
    { query: 'Commercial HVAC Contractor', plural: 'HVAC contractors', pain: 'service dispatching and job-completion review collection' },
    { query: 'Commercial Solar Contractor', plural: 'solar contractors', pain: 'consultation intake and site survey scheduling' },

    // 3. Professional & Business Services
    { query: 'Commercial Law Firm', plural: 'law practices', pain: 'client intake routing and consultation document prep' },
    { query: 'CPA Accounting Firm', plural: 'accounting firms', pain: 'client document collection and onboarding workflows' },
    { query: 'Property Management Company', plural: 'property management teams', pain: 'maintenance request triage and tenant inquiry routing' },
    { query: 'Boutique Advisory Firm', plural: 'consulting firms', pain: 'consult bookings and pre-meeting prep' },
    { query: 'Real Estate Agency', plural: 'real estate brokerages', pain: 'property inquiries and agent lead distribution' },
    { query: 'Staffing Agency', plural: 'recruiting agencies', pain: 'candidate application parsing and interview scheduling' },
    { query: 'Wealth Management Firm', plural: 'wealth management advisors', pain: 'client onboarding and portfolio review scheduling' }
  ],
  'Social Media Manager (SMM)': [
    { query: 'Creative Branding Studio', plural: 'creative studios', pain: 'client case studies and weekly short-form video reels' },
    { query: 'E-commerce Brand', plural: 'e-commerce brands', pain: 'product catalogs and organic social clips' },
    { query: 'Digital Marketing Agency', plural: 'marketing agencies', pain: 'campaign wins and visual LinkedIn carousels' }
  ],
  'Executive VA': [
    { query: 'Boutique Advisory Firm', plural: 'consulting firms', pain: 'executive calendar triage and client prep' },
    { query: 'Commercial Law Firm', plural: 'law firms', pain: 'consultation intake and executive scheduling' },
    { query: 'Accounting Firm', plural: 'accounting firms', pain: 'inbox triage and client document coordination' }
  ],
  'General VA': [
    { query: 'Commercial Roofing Contractor', plural: 'contractors', pain: 'customer inquiry response and job dispatching' },
    { query: 'Property Management Company', plural: 'property managers', pain: 'tenant inquiries and vendor coordination' },
    { query: 'Dental Clinic', plural: 'dental clinics', pain: 'appointment reminders and patient intake follow-up' }
  ]
};

const niches = nichesByRole[role] || nichesByRole['Automation VA'];

// Full combinatorial coverage: cycles through all (cities * niches) without missing combos
const totalCombinations = cities.length * niches.length;
const currentStep = (staticData.rotationIndex - 1) % totalCombinations;
const nicheIndex = currentStep % niches.length;
const cityIndex = Math.floor(currentStep / niches.length) % cities.length;

const targetCity = cities[cityIndex];
const targetNiche = niches[nicheIndex];
const searchQuery = `${targetNiche.query} in ${targetCity}`;

return [{
  json: {
    ...config,
    search_query: searchQuery,
    target_city: targetCity,
    target_category: targetNiche.query,
    category_plural: targetNiche.plural,
    base_pain_area: targetNiche.pain,
    rotation_index: staticData.rotationIndex,
    rotation_coverage: `${cityIndex + 1}/${cities.length} cities, ${nicheIndex + 1}/${niches.length} niches (combo ${currentStep + 1}/${totalCombinations})`
  }
}];

