const items = $input.all();

return items.map((item) => {
  const data = item.json;
  const draft = data.draft || {};
  const bizName = data.clean_business_name || data.business_name || 'Business Partner';
  const greeting = data.greeting || `Hi ${bizName} team,`;
  const senderName = data.sender_name || 'Laurence Supangan';
  const senderFirst = data.sender_first || 'Laurence';
  const portfolioLink = data.portfolio_link || 'itslaurence.dev';
  const physicalAddress = data.sender_physical_address || data.sender_location || '123 Business Way, Manila, 1000, Philippines';

  // Format email_1
  const email1Body = `${greeting}\n\n${draft.email_1}\n\n${senderName}\n${portfolioLink}\n${physicalAddress}\nIf this isn't relevant, reply "no" and I won't email again.`;

  // Format follow-ups
  const f1Body = `${draft.followup_1}\n\n- ${senderFirst}`;
  const f2Body = `${draft.followup_2}\n\n- ${senderFirst}`;
  const f3Body = `${draft.followup_3}\n\n- ${senderFirst}`;

  let reviewStatus = data.review_status || 'Ready to Send';
  if (data.needs_review) {
    reviewStatus = 'Review Required';
  }

  const hookEvidence = draft.hook_evidence || data.signal_fact || '';
  const proofUsed = draft.proof_used || data.proof_point || '';

  const notesWithScore = `${data.icp_score_breakdown || ''}\n[Email: ${data.extracted_email || 'None found'} (${data.email_type || 'none'}) | Domain: ${data.domain || ''}]\n[Chosen Signal: ${draft.chosen_signal || 'default'}]\n\nSubject: ${draft.subject}\n\n${email1Body}`;

  return {
    json: {
      ...data,
      business_name: bizName,
      subject_line: draft.subject || `workflow note for ${(bizName).toLowerCase()}`,
      email_1: email1Body,
      followup_1: f1Body,
      followup_2: f2Body,
      followup_3: f3Body,
      hook_evidence: hookEvidence,
      proof_used: proofUsed,
      review_status: reviewStatus,
      assembled_email: email1Body,
      airtable_notes: notesWithScore
    }
  };
});

const staticData = $getWorkflowStaticData('global');
staticData.seenPlaceIds = staticData.seenPlaceIds || [];
staticData.seenDomains = staticData.seenDomains || [];

// 1. Fetch active CRM domains from native Airtable search
let activeCrmDomains = new Set();
try {
  const atItems = $('Fetch Existing CRM Domains').all();
  for (const item of atItems) {
    const r = item.json;
    const d = (r.fields?.Domain || r.Domain || r.fields?.domain || r.domain || '').toLowerCase().trim();
    if (d) activeCrmDomains.add(d);
  }
} catch (e) {}

// 2. Fetch suppressed domains from native Airtable search
let suppressedDomains = new Set();
try {
  const suppItems = $('Fetch Suppressed Domains').all();
  for (const item of suppItems) {
    const r = item.json;
    const d = (r.fields?.Domain || r.Domain || r.fields?.domain || r.domain || '').toLowerCase().trim();
    if (d) suppressedDomains.add(d);
  }
} catch (e) {}

const items = $input.all();
const freshItems = [];
const batchSeenDomains = new Set();
const batchSeenPlaceIds = new Set();

for (const item of items) {
  const pId = (item.json.place_id || '').trim();
  const rawDom = (item.json.domain || '').trim().toLowerCase();

  // A. Skip if domain already exists in active Companies CRM
  if (rawDom && activeCrmDomains.has(rawDom)) continue;

  // B. Skip if domain is in Suppression List
  if (rawDom && suppressedDomains.has(rawDom)) continue;

  // C. Skip intra-batch duplicates
  if (rawDom && batchSeenDomains.has(rawDom)) continue;
  if (pId && batchSeenPlaceIds.has(pId)) continue;

  // D. Skip duplicates recorded in workflow static data
  const isSeenPlace = pId && staticData.seenPlaceIds.includes(pId);
  const isSeenDomain = rawDom && staticData.seenDomains.includes(rawDom);
  if (isSeenPlace || isSeenDomain) continue;

  if (pId) {
    batchSeenPlaceIds.add(pId);
    staticData.seenPlaceIds.push(pId);
  }
  if (rawDom) {
    batchSeenDomains.add(rawDom);
    staticData.seenDomains.push(rawDom);
  }
  freshItems.push(item);
}

// Keep static array bounded so it doesn't grow indefinitely
if (staticData.seenPlaceIds.length > 5000) staticData.seenPlaceIds = staticData.seenPlaceIds.slice(-2500);
if (staticData.seenDomains.length > 5000) staticData.seenDomains = staticData.seenDomains.slice(-2500);

return freshItems;

const lead = $json;
const cfg = $('Config: VA Profile & Settings').first().json;
const city = lead.target_city || '';
const spelling = /UK|London|Manchester|Australia|Sydney|Melbourne|Brisbane/.test(city)
  ? 'British/Australian (enquiries, organisation, centre)'
  : /Canada|Toronto|Vancouver/.test(city) ? 'Canadian (organization, centre)'
  : 'American (inquiries, organization, center)';

// Title & Role
const professionalTitle = 'workflow automation specialist';
const article = 'a';

let proofs = [];
try { proofs = JSON.parse(cfg.proof_points || '[]'); } catch (e) { proofs = []; }

// Match category and signal
const cat = (lead.target_category || '').toLowerCase();
let categoryKey = 'aaa';
if (/roofing|contractor|construction|hvac|solar|plumb/i.test(cat)) categoryKey = 'contractor';
else if (/real estate|property|realtor|broker/i.test(cat)) categoryKey = 'realestate';
else if (/agency|marketing|digital|creative|seo|branding|web/i.test(cat)) categoryKey = 'agency';
else if (/law|legal|attorney/i.test(cat)) categoryKey = 'legal';
else if (/accounting|cpa|bookkeep/i.test(cat)) categoryKey = 'accounting';
else if (/wealth|financial|advis/i.test(cat)) categoryKey = 'wealth';
else if (/staffing|recruit/i.test(cat)) categoryKey = 'staffing';

let matchingPool = proofs.filter(p => p.categories && p.categories.includes(categoryKey));

// Adjacent examples for Proof Paragraph
let adjacentSteps = 'The same setup works for lead intake, CRM updates, and scheduling handoffs.';
let focusArea = 'inquiry follow-up';

if (categoryKey === 'contractor') {
  adjacentSteps = 'The same setup works for service dispatching, quote follow-ups, and job-completion invoicing.';
  focusArea = 'review follow-up';
} else if (categoryKey === 'realestate') {
  adjacentSteps = 'The same setup works for new portal inquiries, showing requests, and CRM status updates.';
  focusArea = 'property inquiry routing';
} else if (categoryKey === 'agency' || categoryKey === 'aaa') {
  adjacentSteps = 'The same setup works for client onboarding, webhook handoffs, and project board creation.';
  focusArea = 'client onboarding';
} else if (categoryKey === 'legal' || categoryKey === 'accounting') {
  adjacentSteps = 'The same setup works for document collection, intake form triage, and calendar scheduling.';
  focusArea = 'consultation intake';
}

if (matchingPool.length === 0) matchingPool = proofs;

// Format proofs for LLM menu
const proofOptionsFormatted = matchingPool.map((p, idx) => `[Option ${idx + 1}] ${p.text}`).join('\n');

// Format detected signals menu for LLM
const signals = lead.detected_signals || [];
const signalsMenuFormatted = signals.map((s, idx) => `${idx + 1}. [${s.key}] ${s.fact}`).join('\n');

// Claude-refined Dual-Path CTA
const refinedCta = `I'd be glad to map out and build a working sample of that for your setup for free, no call needed. If ${focusArea} isn't your main bottleneck, tell me what is and I'll build a small sample for that instead. Just let me know what tools your team uses and I'll send over a video demo. If it helps, we can talk. If not, no worries.`;

let samples = [];
try { samples = JSON.parse(cfg.writing_samples || '[]'); } catch (e) { samples = []; }
const picked = samples.sort(() => Math.random() - 0.5).slice(0, 2).join('\n---\n');

const cleanName = lead.clean_business_name || lead.business_name || '';

let greeting = `Hi ${cleanName} team,`;
if (cleanName && cleanName.split(' ').length > 3) {
  greeting = 'Hi there,';
}

if (lead.extracted_email) {
  const userPart = lead.extracted_email.split('@')[0].toLowerCase();
  const genericPrefixes = [
    'info', 'contact', 'support', 'sales', 'admin', 'hello', 'office', 'team',
    'help', 'inquiries', 'enquiries', 'service', 'services', 'marketing', 'careers',
    'jobs', 'billing', 'accounting', 'reception', 'hr', 'press', 'media', 'general',
    'frontdesk', 'operations', 'dispatch', 'scheduling', 'estimates'
  ];
  if (!genericPrefixes.includes(userPart) && userPart.length > 2 && !userPart.includes('+')) {
    const formatted = userPart.split('.')[0].replace(/[^a-zA-Z]/g, '');
    if (formatted.length > 2) {
      greeting = `Hi ${formatted.charAt(0).toUpperCase() + formatted.slice(1)},`;
    }
  }
}

return {
  json: {
    ...lead,
    clean_business_name: cleanName,
    professional_title: professionalTitle,
    title_with_article: `${article} ${professionalTitle}`,
    spelling,
    signals_menu: signalsMenuFormatted,
    proof_options: proofOptionsFormatted,
    proof_point: matchingPool[0]?.text || '',
    adjacent_steps: adjacentSteps,
    focus_area: focusArea,
    cta: refinedCta,
    picked_samples: picked,
    voice_notes: cfg.voice_notes || '',
    greeting,
    sender_first: (lead.sender_name || 'Laurence').split(' ')[0]
  }
};

const out = $json.output || $json;

let lead = {};
try {
  lead = $('Prepare Writing Inputs').itemMatching($itemIndex).json;
} catch (e) {
  const allLeads = $('Prepare Writing Inputs').all().map(i => i.json);
  lead = allLeads[$itemIndex] || {};
}

const errors = [];
const wc = s => (s || '').trim().split(/\s+/).filter(Boolean).length;

const KEYS = ['subject','email_1','followup_1','followup_2','followup_3','chosen_signal','hook_evidence','proof_used'];
KEYS.forEach(k => { if (typeof out[k] !== 'string' || !out[k].trim()) errors.push(`missing ${k}`); });

if (!errors.length) {
  // Validate that chosen_signal is in detected_signals
  const detectedKeys = (lead.detected_signals || []).map(s => s.key);
  if (detectedKeys.length > 0 && !detectedKeys.includes(out.chosen_signal)) {
    errors.push(`chosen_signal "${out.chosen_signal}" is not in detected_signals: ${detectedKeys.join(', ')}`);
  }

  const LIMITS = { email_1:[70,185], followup_1:[30,85], followup_2:[20,70], followup_3:[15,55] };
  for (const [k,[lo,hi]] of Object.entries(LIMITS)) {
    const n = wc(out[k]);
    if (n < lo || n > hi) errors.push(`${k} is ${n} words, must be ${lo}-${hi}`);
  }
  const sw = wc(out.subject);
  if (sw < 3 || sw > 8) errors.push(`subject is ${sw} words, must be 3-8`);
  if (out.subject !== out.subject.toLowerCase()) errors.push('subject must be lowercase');

  const all = [out.subject, out.email_1, out.followup_1, out.followup_2, out.followup_3].join('\n');
  if (/[—–]/.test(all)) errors.push('contains em or en dash');
  if (/!/.test(all)) errors.push('contains exclamation mark');

  const cleanedAll = all.replace(/\bwe (can )?talk\b/gi, '');
  if (/\b(our|ours)\b/i.test(cleanedAll) || /\bwe (are|have|build|help|work with)\b/i.test(cleanedAll)) {
    errors.push('uses agency language (our/we are)');
  }

  if (/\b(solo virtual assistant|virtual assistant|business workflow consultant)\b/i.test(all)) {
    errors.push('uses banned title (virtual assistant / business workflow consultant)');
  }

  const BANNED = ['impressive','amazing','great','love','passionate','streamline','leverage',
    'game-changer','cutting-edge','solutions','synergy','hope this finds','reaching out',
    'touch base','just checking in','circle back','following up'];
  BANNED.forEach(w => { if (all.toLowerCase().includes(w)) errors.push(`banned phrase: ${w}`); });

  const q = (out.email_1.match(/\?/g) || []).length;
  if (q < 1 || q > 2) errors.push(`email_1 has ${q} question marks, needs 1 or 2`);
  if (/^(hi|hello|hey|dear)\b/i.test(out.email_1.trim())) errors.push('email_1 includes a greeting');
  if (/\n\s*(best|regards|cheers|thanks|sincerely)\b/i.test(out.email_1)) errors.push('email_1 includes a sign-off');
}

return { json: { ...lead, draft: out, valid: errors.length === 0, errors } };

