const items = $input.all();

const HOOK = {
  booking_flow: 20,
  intake_form: 18,
  tech_crm: 16,
  team_hiring: 14,
  high_rating: 8,
  review_scale: 8,
  review_volume: 6,
  established_team: 4,
  office_presence: 4,
  local_presence: 0
};

return items.map(item => {
  const d = item.json;
  const draft = d.draft || {};
  const chosen = draft.chosen_signal || d.chosen_signal || d.signal_type || 'local_presence';

  let p = (d.icp_score || 0) * 0.35; // fit, 0-35
  const emailScores = { direct: 20, generic: 8, external: 2 };
  p += emailScores[d.email_type] ?? 8;
  p += HOOK[chosen] ?? 0;
  p += (d.has_mail_server || d.mx_valid) ? 5 : 0;

  if (d.needs_review || d.review_status === 'Review Required') p -= 25;
  if (/Canada|Australia/i.test(d.target_city || '')) p -= 15;
  if ((Number(d.reviews_count) || 0) > 500) p -= 10;

  const sendPriority = Math.max(0, Math.min(100, Math.round(p)));

  return {
    json: {
      ...d,
      send_priority: sendPriority
    }
  };
});

const staticData = $getWorkflowStaticData('global');
const today = new Date().toISOString().slice(0, 10);
if (staticData.draftDate !== today) {
  staticData.draftDate = today;
  staticData.draftsToday = 0;
}

const items = $input.all();
const out = [];

for (const item of items) {
  const lead = item.json;
  const score = Number(lead.icp_score || 0);
  const isTierAorB = score >= 65; // Tier A (80+) or Tier B (65-79)
  const underCap = (staticData.draftsToday || 0) < 25;

  if (isTierAorB && underCap) {
    staticData.draftsToday = (staticData.draftsToday || 0) + 1;
    out.push({
      json: {
        ...lead,
        should_draft: true,
        daily_draft_number: staticData.draftsToday
      }
    });
  } else {
    const reason = !isTierAorB ? 'Score below Tier B floor (<65)' : 'Daily LLM draft cap (25) reached';
    out.push({
      json: {
        ...lead,
        should_draft: false,
        review_status: 'Backlog / Unassigned',
        backlog_reason: reason
      }
    });
  }
}

return out;

